import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib

app = Flask(__name__)

UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

os.makedirs(UPLOAD_DIR, exist_ok=True)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def get_output_path(input_path, fmt='pdf'):
    base = os.path.splitext(input_path)[0]
    return f"{base}.{fmt}"

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.4.1"})

@app.route('/convert', methods=['POST'])
def convert_document():
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 415

    output_format = request.form.get('format', 'pdf')
    extra_args = request.form.get('options', '')

    # Generate unique filename to avoid collisions
    filename = secure_filename(file.filename)
    file_hash = hashlib.md5(file.read()).hexdigest()[:8]
    file.seek(0)

    input_path = os.path.join(UPLOAD_DIR, f"{file_hash}_{filename}")
    file.save(input_path)

    # Build LibreOffice conversion command
    # The --headless flag ensures no GUI is spawned
    cmd = f"libreoffice --headless --convert-to {output_format} --outdir {UPLOAD_DIR} {input_path}"

    # Allow power users to pass additional LibreOffice macro options
    if extra_args:
        cmd = f"{cmd} {extra_args}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=UPLOAD_DIR
        )

        if result.returncode != 0:
            return jsonify({
                "error": "Conversion failed",
                "details": result.stderr.decode('utf-8', errors='replace')[:500]
            }), 500

        output_path = get_output_path(input_path, output_format)

        if not os.path.exists(output_path):
            # Try alternative naming convention
            alt_path = os.path.join(UPLOAD_DIR, 
                os.path.splitext(os.path.basename(input_path))[0] + '.' + output_format)
            if os.path.exists(alt_path):
                output_path = alt_path
            else:
                return jsonify({"error": "Output file not found"}), 500

        return send_file(output_path, as_attachment=True,
                        download_name=f"converted.{output_format}")

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    finally:
        # Cleanup input file
        if os.path.exists(input_path):
            os.unlink(input_path)

@app.route('/batch', methods=['POST'])
def batch_convert():
    """Convert multiple files. Accepts multipart form with multiple 'files' fields."""
    files = request.files.getlist('files')
    if not files:
        return jsonify({"error": "No files provided"}), 400

    results = []
    for f in files[:10]:  # Limit to 10 files
        if allowed_file(f.filename):
            results.append({"file": f.filename, "status": "queued"})
        else:
            results.append({"file": f.filename, "status": "rejected"})

    return jsonify({"batch_id": hashlib.md5(os.urandom(16)).hexdigest(), "results": results})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
